import unittest
from candidate import pluck

class TestPluckFunction(unittest.TestCase):
    def test_single_even_element(self):
        self.assertEqual(pluck([4]), [4, 0])

    def test_single_odd_element(self):
        self.assertEqual(pluck([3]), [])

    def test_multiple_even_values_with_min_index(self):
        self.assertEqual(pluck([5, 2, 4, 2]), [2, 1])

    def test_multiple_even_values_same_min(self):
        self.assertEqual(pluck([4, 2, 2, 6]), [2, 1])

    def test_all_odd_values(self):
        self.assertEqual(pluck([1, 3, 5, 7]), [])

    def test_empty_list(self):
        self.assertEqual(pluck([]), [])

    def test_zero_included(self):
        self.assertEqual(pluck([5, 0, 3, 0, 4, 2]), [0, 1])

    def test_min_even_in_middle(self):
        self.assertEqual(pluck([5, 7, 8, 2, 4]), [2, 3])

    def test_input_unchanged(self):
        arr = [2, 4, 6]
        copy = list(arr)
        pluck(arr)
        self.assertEqual(arr, copy)

    def test_tuple_input(self):
        self.assertEqual(pluck((8, 3, 2, 5)), [2, 2])

    def test_set_input_raises(self):
        with self.assertRaises(AttributeError):
            pluck({2, 3, 4})

    def test_non_integer_in_list_raises_type_error(self):
        with self.assertRaises(TypeError):
            pluck([2, 'a', 4])

    def test_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            pluck(None)

    def test_large_input_performance(self):
        large_arr = list(range(10000))
        result = pluck(large_arr)
        self.assertEqual(result, [0, 0])

    def test_even_values_negative(self):
        self.assertEqual(pluck([-4, -2, 0, 2]), [-4, 0])

    def test_return_type_is_list(self):
        result = pluck([2, 4, 6])
        self.assertIsInstance(result, list)

    def test_index_of_first_min_even(self):
        self.assertEqual(pluck([4, 2, 2, 4]), [2, 1])

    def test_multiple_min_even_multiple_occurrences(self):
        self.assertEqual(pluck([2, 4, 2, 6, 2]), [2, 0])

    def test_index_retrieved_from_list(self):
        arr = [3, 6, 8, 2, 4]
        expected_index = arr.index(2)
        self.assertEqual(pluck(arr)[1], expected_index)

    def test_pluck_on_list_of_strings_raises(self):
        with self.assertRaises(TypeError):
            pluck(['1', '2', '3'])

    def test_pluck_on_mixed_numeric_strings_and_ints_raises(self):
        with self.assertRaises(TypeError):
            pluck([1, '2', 3])

    def test_pluck_on_boolean_list_returns_even(self):
        self.assertEqual(pluck([True, False]), [False, 1])

    def test_pluck_on_empty_tuple_returns_empty_list(self):
        self.assertEqual(pluck(()), [])

if __name__ == "__main__":
    unittest.main()
